export function decideAction(faction,H){
 const weights = {
  expand: H[0] + H[6],
  trade: H[3] + H[2],
  innovate: H[5] + H[12],
  war: H[9] + H[11],
  stabilize: H[4]
 };
 return Object.keys(weights).reduce((a,b)=> weights[a]>weights[b]?a:b);
}

AI Action Execution.Code:
export async function executeAction(faction,action){
 switch(action){
  case 'expand': faction.territory+=1; break;
  case 'trade': faction.resources+=10; break;
  case 'innovate': faction.knowledge+=5; break;
  case 'war': faction.power+=2; break;
  case 'stabilize': faction.resources-=2; break;
 }
 return faction;
}

